    internal InnerInstanceFleetConfigSpotResizingSpecificationFactory SpotResizeSpecificationFactory { get; set; }

    protected override Humidifier.EMR.InstanceFleetConfigTypes.InstanceFleetResizingSpecifications Create()
    {
        var instanceFleetResizingSpecificationsResult = CreateInstanceFleetResizingSpecifications();
        factoryAction?.Invoke(instanceFleetResizingSpecificationsResult);

        return instanceFleetResizingSpecificationsResult;
    }

    private Humidifier.EMR.InstanceFleetConfigTypes.InstanceFleetResizingSpecifications CreateInstanceFleetResizingSpecifications()
    {
        var instanceFleetResizingSpecificationsResult = new Humidifier.EMR.InstanceFleetConfigTypes.InstanceFleetResizingSpecifications();

        return instanceFleetResizingSpecificationsResult;
    }
    public override void CreateChildren(Humidifier.EMR.InstanceFleetConfigTypes.InstanceFleetResizingSpecifications result)
    {
        base.CreateChildren(result);

        result.OnDemandResizeSpecification ??= OnDemandResizeSpecificationFactory?.Build();
        result.SpotResizeSpecification ??= SpotResizeSpecificationFactory?.Build();
    }

} // End Of Class

